package cl.bolsillo.app;
import org.json.*;import java.util.*;
/** Previous versions of edited or deleted records remain inside the encrypted local ledger. */
final class ChangeHistory {
 static Map<String,Map<String,String>> snapshot(JSONObject d)throws Exception{Map<String,Map<String,String>> result=new LinkedHashMap<>();for(String key:new String[]{"transactions","receivables","planned","recurring","accounts","people","budgets","goals","categories"}){Map<String,String> items=new LinkedHashMap<>();JSONArray list=d.optJSONArray(key);if(list!=null)for(int i=0;i<list.length();i++){JSONObject item=list.getJSONObject(i);items.put(item.getString("id"),item.toString());}result.put(key,items);}return result;}
 static void record(JSONObject d,Map<String,Map<String,String>> previous)throws Exception{Map<String,Map<String,String>> current=snapshot(d);JSONArray log=d.getJSONArray("changeLog");for(String key:previous.keySet()){Map<String,String> before=previous.get(key),after=current.get(key);for(Map.Entry<String,String> old:before.entrySet()){String next=after.get(old.getKey());if(next==null||!old.getValue().equals(next)){Ledger.require(log.length()<100000,"El historial llegó al límite; exporta un respaldo");log.put(new JSONObject().put("id",Ledger.id()).put("at",System.currentTimeMillis()).put("section",key).put("recordId",old.getKey()).put("action",next==null?"deleted":"edited").put("before",new JSONObject(old.getValue())).put("after",next==null?JSONObject.NULL:new JSONObject(next)));}}}}
 static String describe(MainActivity a,JSONObject value){if(value==null)return "Registro eliminado";StringBuilder text=new StringBuilder();for(String[] field:new String[][]{{"name","Nombre"},{"amount","Monto"},{"settled","Abonado"},{"date","Fecha"},{"note","Nota"},{"status","Estado"},{"account","Cuenta"},{"category","Categoría"}}){String key=field[0];if(value.has(key)&&!value.optString(key).isEmpty()){String detail=key.equals("amount")||key.equals("settled")?a.money(value.optLong(key)):value.optString(key);text.append(field[1]).append(": ").append(detail).append('\n');}}return text.toString().trim();}
 static void show(MainActivity a)throws Exception{JSONArray log=a.data.getJSONArray("changeLog");Modern.section(a,"Cambios guardados","",()->{});a.caption("Ediciones y eliminaciones. Los movimientos vigentes siguen en Actividad.");if(log.length()==0){a.caption("Todavía no hay cambios de registros.");return;}int start=log.length()-1-a.page*25;if(start<0){a.page=0;start=log.length()-1;}for(int i=start;i>=Math.max(0,start-24);i--){JSONObject e=log.getJSONObject(i),old=e.getJSONObject("before"),now=e.optJSONObject("after");String title=old.optString("note").isEmpty()?old.optString("name",e.optString("section")):old.optString("note");if(title.length()>60)title=title.substring(0,60)+"…";String subtitle=Detection.date(e.optLong("at"))+" · "+(e.optString("action").equals("deleted")?"Eliminado":"Editado");String amount=old.has("amount")?a.money(old.optLong("amount")):"";Modern.add(a.body,Modern.item(a,e.optString("action").equals("deleted")?"delete":"activity",title,subtitle,amount,Glass.VIOLET,()->NativeSettings.info(a,"Antes\n"+describe(a,old)+"\n\nDespués\n"+describe(a,now))),6);}a.caption((log.length()-start)+"–"+Math.min(log.length(),log.length()-start+24)+" de "+log.length());if(a.page>0)a.action("Más recientes",()->{a.page--;a.render();});if(start>=25)a.action("Más antiguos",()->{a.page++;a.render();});}
}
